import SliceAccordion from "@/registry/open-source/slice-accordion";

export default function Usage() {
	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-background">
			<SliceAccordion />
		</div>
	);
}

import { useState } from "react";

interface OptionData {
	id: number;
	background: string;
	icon: string;
	main: string;
	sub: string;
	defaultColor: string;
}

const SliceAccordion = () => {
	const [activeOption, setActiveOption] = useState<number>(0);

	const optionsData: OptionData[] = [
		{
			id: 0,
			background: "/itjustworks.jpg",
			icon: "fas fa-glasses",
			main: "cool cat",
			sub: "living the sunglasses life",
			defaultColor: "#ED5565",
		},
		{
			id: 1,
			background: "/itjustworks.jpg",
			icon: "fas fa-sun",
			main: "poolside vibes",
			sub: "summer hat game strong",
			defaultColor: "#FC6E51",
		},
		{
			id: 2,
			background: "/itjustworks.jpg",
			icon: "fas fa-box",
			main: "box explorer",
			sub: "if i fits, i sits",
			defaultColor: "#FFCE54",
		},
		{
			id: 3,
			background: "/itjustworks.jpg",
			icon: "fas fa-cookie-bite",
			main: "snack time",
			sub: "nom nom nom",
			defaultColor: "#2ECC71",
		},
		{
			id: 4,
			background: "/itjustworks.jpg",
			icon: "fas fa-star",
			main: "cosmic kitty",
			sub: "exploring the universe",
			defaultColor: "#5D9CEC",
		},
	];

	const handleOptionClick = (optionId: number) => {
		setActiveOption(optionId);
	};
	return (
		<div className="options-container">
			<div className="options-wrapper">
				{optionsData.map((option) => (
					<div
						key={option.id}
						className={`option-item ${activeOption === option.id ? "active" : ""}`}
						style={
							{
								backgroundImage: `url(${option.background})`,
								backgroundSize:
									option.id === 1 || option.id === 2 || option.id === 4
										? "cover"
										: undefined,
								"--defaultBackground": option.defaultColor,
							} as React.CSSProperties
						}
						onClick={() => handleOptionClick(option.id)}
					>
						<div className="option-shadow"></div>
						<div className="option-label">
							<div
								className="option-icon"
								style={{
									color: "#C0C0C0",
									textShadow:
										"0 1px 2px rgba(0,0,0,0.3), 0 0 8px rgba(255,255,255,0.5)",
									filter: "drop-shadow(0 0 2px rgba(255,255,255,0.8))",
								}}
							>
								<i className={option.icon}></i>
							</div>
							<div className="option-info">
								<div className="option-main font-mono">
									{option.main}
								</div>
								<div className="option-sub font-mono">{option.sub}</div>
							</div>
						</div>
					</div>
				))}

				<div className="inactive-options">
					{optionsData.map(
						(option) =>
							option.id !== activeOption && (
								<div
									key={option.id}
									className="inactive-option"
									style={{
										backgroundImage: `url(${option.background})`,
									}}
									onClick={() => handleOptionClick(option.id)}
								>
									<div className="inactive-option-inner">
										<i
											className={option.icon}
											style={{ color: option.defaultColor }}
										></i>
									</div>
								</div>
							)
					)}
				</div>
			</div>
		</div>
	);
};

export default SliceAccordion;
